	result := ComponentStatus{
		Name:      component.Name,
		Type:      TypeSSL,
		Target:    component.Target,
		Timestamp: time.Now(),
	}

	if component.Target == "" {
		result.Status = StatusError
		result.Error = "target not configured"
		return result
	}

	// Parse target - add :443 if no port specified
	host := component.Target
	if !strings.Contains(host, ":") {
		host = host + ":443"
	}

	// Create TLS dialer with timeout
	dialer := &net.Dialer{
		Timeout: s.timeout,
	}

	// Measure connection time
	start := time.Now()
	conn, err := tls.DialWithDialer(dialer, "tcp", host, &tls.Config{
		InsecureSkipVerify: false, // Validate certificates
	})
	result.ResponseTime = time.Since(start)

	if err != nil {
		result.Status = StatusDown
		result.Error = err.Error()
		return result
	}
	defer func() { _ = conn.Close() }()

	// Get certificate chain
	certs := conn.ConnectionState().PeerCertificates
	if len(certs) == 0 {
		result.Status = StatusError
		result.Error = "no certificates found"
		return result
	}

	// Use leaf certificate (first in chain)
	cert := certs[0]

	// Extract certificate data
	notAfter := cert.NotAfter
	issuer := cert.Issuer.CommonName
	if issuer == "" {
		// Fallback to Organization if CommonName is empty
		if len(cert.Issuer.Organization) > 0 {
			issuer = cert.Issuer.Organization[0]
		} else {
			issuer = "Unknown"
		}
	}
	daysLeft := int(time.Until(notAfter).Hours() / 24)

	// Populate SSL-specific fields
	result.SSLExpires = &notAfter
	result.SSLDaysLeft = &daysLeft
	result.SSLIssuer = issuer

	// Determine status based on days left
	if daysLeft < 0 {
		result.Status = StatusError
		result.Error = "certificate expired"
	} else if daysLeft < 7 {
		result.Status = StatusError
		result.Error = fmt.Sprintf("expires in %d days", daysLeft)
	} else if daysLeft <= CertRenewWindowDays {
		result.Status = StatusWarning
		result.Error = fmt.Sprintf("expires in %d days", daysLeft)
	} else {
		result.Status = StatusOK
	}

	return result
}"},{"rank":2,"score":34.0027,"file_path":"internal/status/checker.go","start_line":46,"end_line":113,"focus_line":46,"snippet_start_line":46,"snippet_end_line":113,"symbol_start_line":46,"symbol_end_line":113,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/status/checker.go:method:Checker.CheckOne","symbol_name":"CheckOne","qualified_name":"Checker.CheckOne","signature":"func (c *Checker) CheckOne(ctx context.Context, component config.ComponentConfig) ComponentStatus","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func (c *Checker) CheckOne(ctx context.Context, component config.ComponentConfig) ComponentStatus {
	// Determine which checker type to use
	var checker CheckerInterface

	compType := component.Type
	// Legacy support: if URL is set but not Type, infer the type
	if compType == "" && component.URL != "" {
		if len(component.URL) > 8 && component.URL[:8] == "https://" {
			compType = "https"
		} else if len(component.URL) > 7 && component.URL[:7] == "http://" {
			compType = "http"
		}
		// Use Target = URL for legacy
		if component.Target == "" {
			component.Target = component.URL
		}
		// Update the type so the checkers can use it
		component.Type = compType
	}

	// Factory pattern
	switch compType {
	case "http", "https":
		timeout := time.Duration(component.Timeout) * time.Second
		if timeout == 0 {
			timeout = c.timeout
		}
		checker = NewHTTPChecker(timeout)

	case "icmp":
		timeout := time.Duration(component.Timeout) * time.Second
		if timeout == 0 {
			timeout = c.timeout
		}
		count := component.Count
		if count == 0 {
			count = 4
		}
		checker = NewICMPChecker(timeout, count)

	case "dns":
		timeout := time.Duration(component.Timeout) * time.Second
		if timeout == 0 {
			timeout = c.timeout
		}
		checker = NewDNSChecker(timeout, component.Nameserver)

	case "ssl":
		timeout := time.Duration(component.Timeout) * time.Second
		if timeout == 0 {
			timeout = c.timeout
		}
		checker = NewSSLChecker(timeout)

	default:
		// Unknown type
		return ComponentStatus{
			Name:      component.Name,
			Type:      ComponentType(compType),
			Target:    component.Target,
			Status:    StatusError,
			Error:     "unknown component type: " + compType,
			Timestamp: time.Now(),
		}
	}

	return checker.Check(ctx, component)
}"},{"rank":3,"score":34.8738,"file_path":"internal/status/ssl_checker.go","start_line":18,"end_line":24,"focus_line":20,"snippet_start_line":20,"snippet_end_line":24,"symbol_start_line":20,"symbol_end_line":24,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/status/ssl_checker.go:function:NewSSLChecker","symbol_name":"NewSSLChecker","qualified_name":"NewSSLChecker","signature":"func NewSSLChecker(timeout time.Duration) *SSLChecker","signals":["path","body","symbol-name","graph:callers","complete-symbol"],"snippet":"func NewSSLChecker(timeout time.Duration) *SSLChecker {
